function MobileExam({ user, onNavigate }) {
  const params = new URLSearchParams(window.location.search);
  const requestedSubject = params.get("subject");
  const requestedSection = params.get("section");
  const [subject, setSubject] = useState(SUBJECTS_11408.some(([key]) => key === requestedSubject) ? requestedSubject : SUBJECTS_11408[0][0]);
  const [section, setSection] = useState(["plan", "papers", "wrong", "ai"].includes(requestedSection) ? requestedSection : "plan");
  useEffect(() => { if (SUBJECTS_11408.some(([key]) => key === requestedSubject)) setSubject(requestedSubject); if (["plan", "papers", "wrong", "ai"].includes(requestedSection)) setSection(requestedSection); }, [requestedSection, requestedSubject]);
  const planState = useMobileRequest(() => jsonFetch(`/exam/11408/subjects/${subject}/study-plan?username=${encodeURIComponent(user.username)}`), [subject, user.username]);
  const papersState = useMobileRequest(() => jsonFetch(`/exam/11408/${subject}/past-papers?username=${encodeURIComponent(user.username)}`), [subject, user.username]);
  const wrongState = useMobileRequest(() => jsonFetch(`/exam/11408/${subject}/wrong-questions?username=${encodeURIComponent(user.username)}`), [subject, user.username]);
  const aiState = useMobileRequest(() => jsonFetch(`/exam/11408/${subject}/ai-questions?username=${encodeURIComponent(user.username)}`), [subject, user.username]);
  const tracksState = useMobileRequest(() => jsonFetch(`/me/tracks?username=${encodeURIComponent(user.username)}`), [user.username]);
  const tasksState = useMobileRequest(() => jsonFetch(`/exam/11408/study-plan/tasks/summary?username=${encodeURIComponent(user.username)}`), [user.username]);
  const [startingPaper, setStartingPaper] = useState("");
  const [paperActionError, setPaperActionError] = useState("");
  const selectedName = SUBJECTS_11408.find(([key]) => key === subject)?.[1] || "11408";
  const active = section === "plan" ? planState : section === "papers" ? papersState : section === "wrong" ? wrongState : aiState;
  const items = section === "plan" ? safeArray(planState.data?.chapters || planState.data?.items) : section === "papers" ? safeArray(papersState.data?.items || papersState.data?.papers) : section === "wrong" ? safeArray(wrongState.data?.items) : safeArray(aiState.data?.items);
  const examTrack = tracksState.status === "success" ? safeArray(tracksState.data?.tracks).find((track) => track.track_type === "exam_408") : null;
  const target = examTrack?.onboarding_detail?.target_school || "";
  const examTime = examTrack?.onboarding_detail?.exam_time || "";
  const tasks = tasksState.status === "success" ? safeArray(tasksState.data?.tasks).filter((task) => displayText(task, ["title", "name"])) : [];
  const startPastPaper = async (paper) => { const year = Number(paper?.year); if (!Number.isInteger(year) || year <= 0) { setPaperActionError("服务端真题数据未提供有效年份，无法创建真实训练。 "); return; } setStartingPaper(String(year)); setPaperActionError(""); try { const data = await jsonFetch(`/exam/11408/${subject}/past-paper-attempts`, { method: "POST", body: JSON.stringify({ username: user.username, year }) }); const attemptId = data.attempt_id || data.id; if (!attemptId) throw new Error("服务端未返回答题记录标识"); onNavigate(`/m/11408/paper/${encodeURIComponent(subject)}/${encodeURIComponent(attemptId)}`); } catch (reason) { setPaperActionError(apiErrorMessage(reason)); } finally { setStartingPaper(""); } };
  return <div className="mobile-page mobile-exam-page"><div className="mobile-page-heading"><div><span className="mobile-eyebrow">11408</span><h1>11408考研中心</h1><p>真题、错题、AI智能训练和学习计划独立于课程学习。</p></div><button className="mobile-small-button" onClick={() => onNavigate(`/m/ai/chat/new?mode=exam&subject=${encodeURIComponent(subject)}`)}>AI 解析</button></div><section className="mobile-exam-overview"><div className="mobile-exam-countdown"><span>考试目标</span><strong>{tracksState.status === "loading" ? "读取中…" : target || "暂无数据"}</strong><small>{examTime || (tracksState.status === "error" ? "目标数据暂不可用" : "服务端未提供考试日期")}</small></div><div className="mobile-exam-task-summary"><span>今日任务</span><strong>{tasksState.status === "loading" ? "读取中…" : tasks.length ? `${tasks.length} 项` : "暂无数据"}</strong><small>{tasks.length ? displayText(tasks[0], ["title", "name"]) : tasksState.status === "error" ? "任务数据暂不可用" : "服务端未返回今日任务"}</small></div></section><div className="mobile-subject-grid">{SUBJECTS_11408.map(([key, label]) => <button key={key} className={subject === key ? "is-active" : ""} onClick={() => { setSubject(key); setSection("plan"); }}><strong>{label}</strong><small>{key === subject ? "当前科目" : "进入专项"}</small></button>)}</div><div className="mobile-exam-section-tabs">{[["plan", "学习计划"], ["papers", "真题"], ["wrong", "错题"], ["ai", "AI智能训练"]].map(([key, label]) => <button key={key} className={section === key ? "is-active" : ""} onClick={() => setSection(key)}>{label}</button>)}</div>{active.status === "loading" ? <LoadingState /> : active.status === "error" ? <ErrorState message={active.error} onRetry={active.retry} /> : items.length ? <section className="mobile-exam-data-list"><SectionTitle title={`${selectedName} · ${section === "plan" ? "学习计划" : section === "papers" ? "真题" : section === "wrong" ? "错题" : "AI智能训练"}`} />{items.slice(0, 20).map((item, index) => <article key={item.id || item.code || index}><strong>{displayText(item, ["title", "name", "stem", "chapter_title"]) || "服务端数据缺少标题"}</strong>{section === "papers" && <><small>{Number.isInteger(Number(item.year)) ? `${item.year} 年` : "年份未提供"}</small>{Number.isInteger(Number(item.year)) && <button className="mobile-small-button" disabled={startingPaper === String(item.year)} onClick={() => startPastPaper(item)}>{startingPaper === String(item.year) ? "创建训练中…" : "开始训练"}</button>}</>}{displayText(item, ["knowledge_point_name", "description", "summary", "status"]) && <p>{displayText(item, ["knowledge_point_name", "description", "summary", "status"])}</p>}{section === "wrong" && item.mastered !== undefined && <small>{item.mastered ? "已掌握" : "待复习"}</small>}</article>)}{paperActionError && <ErrorState message={paperActionError} />}</section> : <EmptyState title={section === "wrong" ? "暂无错题" : "暂无数据"} description={section === "plan" ? "服务端未返回该科目学习计划。" : section === "papers" ? "服务端未返回该科目真题。" : section === "ai" ? "服务端未返回 AI 题目。" : "服务端未返回该科目错题。"} />}</div>;
}

function MobilePastPaperAttempt({ user, onNavigate }) {
  const match = window.location.pathname.match(/^\/m\/11408\/paper\/([a-z_]+)\/(\d+)$/);
  const subject = match?.[1] || "";
  const attemptId = match?.[2] || "";
  const state = useMobileRequest(() => jsonFetch(`/exam/11408/${encodeURIComponent(subject)}/past-paper-attempts/${encodeURIComponent(attemptId)}?username=${encodeURIComponent(user.username)}`), [subject, attemptId, user.username], Boolean(subject && attemptId));
  const [answers, setAnswers] = useState({});
  const [submitting, setSubmitting] = useState(false);
  const [submitError, setSubmitError] = useState("");
  const [submitted, setSubmitted] = useState(null);
  useEffect(() => { if (state.status === "success") setAnswers(state.data?.saved_answers || {}); }, [state.status, state.data]);
  if (state.status !== "success") return <div className="mobile-page"><AsyncState state={state} empty={<EmptyState title="答题记录不可用" description="服务端没有返回可继续的真题训练。" />} /></div>;
  const questions = safeArray(state.data?.questions);
  const subjectName = SUBJECTS_11408.find(([key]) => key === subject)?.[1] || "11408";
  const saveAnswer = (key, value) => setAnswers((current) => ({ ...current, [key]: value }));
  const submit = async () => { setSubmitting(true); setSubmitError(""); try { const data = await jsonFetch(`/exam/11408/${encodeURIComponent(subject)}/past-paper-attempts/${encodeURIComponent(attemptId)}/submit`, { method: "POST", body: JSON.stringify({ username: user.username, answers }) }); setSubmitted(data); } catch (reason) { setSubmitError(apiErrorMessage(reason)); } finally { setSubmitting(false); } };
  return <div className="mobile-page mobile-paper-attempt"><div className="mobile-page-heading"><div><span className="mobile-eyebrow">{subjectName}</span><h1>真题训练</h1><p>题目与答题记录均来自现有 11408 真题接口。</p></div><button className="mobile-small-button" onClick={() => onNavigate(`/m/11408?subject=${encodeURIComponent(subject)}&section=papers`)}>返回真题</button></div>{submitted ? <section className="mobile-result is-correct"><strong>提交完成</strong><p>{submitted.summary || `已提交 ${submitted.total_questions ?? questions.length} 题`}</p></section> : questions.length ? <><div className="mobile-paper-attempt-list">{questions.map((question, index) => { const key = String(question.id || question.question_id || index); const options = question.options && typeof question.options === "object" ? Object.entries(question.options) : safeArray(question.options).map((value, optionIndex) => [String.fromCharCode(65 + optionIndex), value]); return <article key={key} className="mobile-question-card"><span className="mobile-question-meta">第 {index + 1} 题</span><h2>{displayText(question, ["stem", "question", "content", "title"]) || "题干未提供"}</h2>{options.length ? <div className="mobile-choice-list">{options.map(([optionKey, optionValue]) => <button key={optionKey} className={String(answers[key] || "") === String(optionKey) ? "is-selected" : ""} onClick={() => saveAnswer(key, optionKey)}><span>{optionKey}</span>{typeof optionValue === "string" ? optionValue : displayText(optionValue, ["text", "label", "value"])}</button>)}</div> : <textarea className="mobile-answer-input" value={answers[key] || ""} onChange={(event) => saveAnswer(key, event.target.value)} placeholder="输入答案" rows="4" />}</article>; })}</div>{submitError && <ErrorState message={submitError} />}<button className="mobile-primary mobile-submit" disabled={submitting} onClick={submit}>{submitting ? "提交中…" : "提交真题"}</button></> : <EmptyState title="暂无真题题目" description="服务端创建了训练，但没有返回题目内容。" />}</div>;
}

function MobileLearningSpaceProgress({ user, mode }) {
  const courseState = useMobileCourse(user);
  const courseDashboard = useMobileRequest(() => jsonFetch(`/course-dashboard?username=${encodeURIComponent(user.username)}&course=${encodeURIComponent(courseState.course)}`), [user.username, courseState.course], mode === "course" && courseState.status === "success");
  const examSummary = useMobileRequest(() => jsonFetch(`/exam/11408/study-plan/summary?username=${encodeURIComponent(user.username)}`), [user.username], mode === "exam");
  const examCounts = useMobileRequest(async () => {
    const result = await Promise.all(SUBJECTS_11408.map(async ([key]) => {
      const [papers, wrong] = await Promise.all([
        jsonFetch(`/exam/11408/${key}/past-papers?username=${encodeURIComponent(user.username)}`),
        jsonFetch(`/exam/11408/${key}/wrong-questions?username=${encodeURIComponent(user.username)}`),
      ]);
      return { papers: safeArray(papers?.items || papers?.papers).length, wrong: safeArray(wrong?.items || wrong?.wrong_questions).length };
    }));
    return result.reduce((total, item) => ({ papers: total.papers + item.papers, wrong: total.wrong + item.wrong }), { papers: 0, wrong: 0 });
  }, [user.username], mode === "exam");
  if (mode === "course") {
    if (courseState.status !== "success") return <section className="mobile-space-progress"><SectionTitle title="课程进度" /><AsyncState state={courseState} empty={<EmptyState compact title="暂无课程" description="服务端没有返回当前课程。" />} /></section>;
    if (courseDashboard.status !== "success") return <section className="mobile-space-progress"><SectionTitle title="课程进度" /><AsyncState state={courseDashboard} empty={<EmptyState compact title="暂无课程进度" description="服务端没有返回当前课程进度。" />} /></section>;
    const value = courseDashboard.data?.progress?.percentage ?? courseDashboard.data?.progress?.percent;
    const percent = Number(value);
    return <section className="mobile-space-progress"><SectionTitle title="课程进度" /><div className="mobile-space-progress-card"><strong>{courseState.courseName}</strong><b>{value === null || value === undefined || value === "" || !Number.isFinite(percent) ? "暂无数据" : `${Math.round(percent)}%`}</b>{Number.isFinite(percent) && <span><i style={{ width: `${Math.min(100, Math.max(0, percent))}%` }} /></span>}<small>由当前账号的课程学习记录计算</small></div></section>;
  }
  if (examSummary.status !== "success" || examCounts.status !== "success") { const state = examSummary.status === "error" ? examSummary : examCounts.status === "error" ? examCounts : examSummary.status === "loading" || examCounts.status === "loading" ? { status: "loading" } : { status: "empty" }; return <section className="mobile-space-progress"><SectionTitle title="11408 学习进度" /><AsyncState state={state} empty={<EmptyState compact title="暂无 11408 进度" description="服务端没有返回专项学习数据。" />} /></section>; }
  const subjects = safeArray(examSummary.data?.subjects);
  return <section className="mobile-space-progress"><SectionTitle title="11408 学习进度" /><div className="mobile-space-progress-grid">{SUBJECTS_11408.map(([key, label]) => { const item = subjects.find((entry) => entry.subject_key === key); const value = Number(item?.overall_progress); const known = Boolean(item?.has_activity) && Number.isFinite(value); return <div key={key}><strong>{label}</strong><b>{known ? `${Math.round(value)}%` : "暂无数据"}</b><small>{item?.has_activity ? `${item.sections_completed ?? 0}/${item.total_sections ?? 0} 章节` : "暂无学习记录"}</small></div>; })}</div><div className="mobile-space-counts"><span>真题 <b>{examCounts.data.papers}</b></span><span>错题 <b>{examCounts.data.wrong}</b></span></div></section>;
}

function MobileLearningSpaceActions({ mode, onNavigate }) {
  const courseActions = [["知识图谱", "/m/learn", "章节与知识点"], ["章节练习", "/m/tasks", "当前课程题目"], ["AI 辅导", "/m/ai", "课程上下文对话"]];
  const examActions = [["真题", "/m/11408?section=papers", "按科目查看"], ["错题本", "/m/11408?section=wrong", "服务端错题记录"], ["AI智能训练", "/m/11408?section=ai", "服务端 AI 题目"], ["学习计划", "/m/11408?section=plan", "四科章节计划"]];
  const actions = mode === "exam" ? examActions : courseActions;
  return <section className="mobile-space-actions"><SectionTitle title={mode === "exam" ? "11408 功能入口" : "课程学习入口"} /><div className="mobile-action-grid">{actions.map(([title, path, detail]) => <button key={title} onClick={() => onNavigate(path)}><strong>{title}</strong><small>{detail}</small></button>)}</div>{mode === "course" && <div className="mobile-space-unavailable"><strong>学习报告</strong><small>现有移动端尚无独立报告页，未创建无数据来源的替代入口。</small></div>}</section>;
}

function MobileAccountDialog({ kind, user, profile, onClose, onUpdated }) {
  const [nickname, setNickname] = useState(profile.nickname || "");
  const [password, setPassword] = useState({ old_password: "", new_password: "", confirm_password: "" });
  const [email, setEmail] = useState(profile.email || "");
  const [code, setCode] = useState("");
  const [emailStep, setEmailStep] = useState(kind === "email" ? "address" : "code");
  const [error, setError] = useState("");
  const [busy, setBusy] = useState(false);
  if (!kind) return null;
  const request = async (action, close = true) => { setBusy(true); setError(""); try { const data = await action(); if (close) onClose(data); } catch (reason) { setError(apiErrorMessage(reason)); } finally { setBusy(false); } };
  const title = kind === "nickname" ? "修改昵称" : kind === "password" ? "修改密码" : "绑定邮箱";
  return <div className="mobile-modal-backdrop" onClick={() => !busy && onClose()} role="presentation"><section className="mobile-account-modal" role="dialog" aria-modal="true" onClick={(event) => event.stopPropagation()}><header><h2>{title}</h2><button onClick={() => onClose()} aria-label="关闭">×</button></header>{kind === "nickname" && <><label>昵称<input value={nickname} onChange={(event) => setNickname(event.target.value)} maxLength="30" /></label><button className="mobile-primary" disabled={busy || !nickname.trim()} onClick={() => request(async () => { const data = await jsonFetch(`/me/profile?username=${encodeURIComponent(user.username)}`, { method: "PUT", body: JSON.stringify({ nickname: nickname.trim() }) }); onUpdated(data.profile || data); return data; })}>{busy ? "保存中…" : "保存"}</button></>}{kind === "password" && <><label>当前密码<input type="password" value={password.old_password} onChange={(event) => setPassword({ ...password, old_password: event.target.value })} /></label><label>新密码<input type="password" value={password.new_password} onChange={(event) => setPassword({ ...password, new_password: event.target.value })} /></label><label>确认新密码<input type="password" value={password.confirm_password} onChange={(event) => setPassword({ ...password, confirm_password: event.target.value })} /></label><button className="mobile-primary" disabled={busy} onClick={() => request(() => jsonFetch(`/me/password?username=${encodeURIComponent(user.username)}`, { method: "PUT", body: JSON.stringify(password) }))}>{busy ? "提交中…" : "确认修改"}</button></>}{kind === "email" && (emailStep === "address" ? <><label>邮箱<input type="email" value={email} onChange={(event) => setEmail(event.target.value)} /></label><button className="mobile-primary" disabled={busy || !email} onClick={() => request(async () => { await jsonFetch(`/me/email/send-code?username=${encodeURIComponent(user.username)}`, { method: "POST", body: JSON.stringify({ email }) }); setEmailStep("code"); }, false)}>{busy ? "发送中…" : "发送验证码"}</button></> : <><label>验证码<input value={code} onChange={(event) => setCode(event.target.value)} inputMode="numeric" maxLength="6" /></label><button className="mobile-primary" disabled={busy || !code} onClick={() => request(async () => { const data = await jsonFetch(`/me/email/verify?username=${encodeURIComponent(user.username)}`, { method: "PUT", body: JSON.stringify({ email, code }) }); onUpdated(data.profile || data); return data; })}>{busy ? "验证中…" : "确认绑定"}</button></>)}{error && <div className="mobile-error" role="alert">{error}</div>}</section></div>;
}
function MobileProfile({ user, onLogout, onNavigate, onUserUpdate }) {
  const state = useMobileRequest(() => jsonFetch(`/me/profile?username=${encodeURIComponent(user.username)}`), [user.username]);
  const [mode, setMode] = useState(readMobileSpace);
  const [dialog, setDialog] = useState("");
  const [notice, setNotice] = useState("");
  const avatarInput = useRef(null);
  if (state.status !== "success") return <div className="mobile-page"><AsyncState state={state} empty={<EmptyState title="暂无账号资料" />} /></div>;
  const profile = state.data?.profile || state.data;
  const saveProfile = (updated) => { const next = { ...user, ...updated }; onUserUpdate(next); state.retry(); setDialog(""); setNotice("已保存"); };
  const uploadAvatar = async (event) => { const file = event.target.files?.[0]; event.target.value = ""; if (!file) return; if (!["image/jpeg", "image/png", "image/webp"].includes(file.type) || file.size > 3 * 1024 * 1024) { setNotice("头像仅支持 3MB 以内的 JPG、PNG 或 WebP"); return; } try { const body = new FormData(); body.append("file", file); body.append("username", user.username); const response = await fetch(`${API_BASE}/me/avatar`, { method: "POST", credentials: "include", body }); const data = await response.json().catch(() => null); if (!response.ok) throw new Error(data?.detail || `上传失败（${response.status}）`); saveProfile(data.profile || data); } catch (reason) { setNotice(apiErrorMessage(reason)); } };
  const switchMode = (nextMode) => { const next = saveMobileSpace(nextMode); setMode(next); onNavigate(next === "exam" ? "/m/11408" : "/m"); };
  const name = profile.nickname || profile.username || user.username;
  const signature = displayText(profile, ["signature", "bio", "introduction"]);
  return <div className="mobile-page mobile-v5-profile"><input ref={avatarInput} className="mobile-visually-hidden" type="file" accept="image/jpeg,image/png,image/webp" onChange={uploadAvatar} /><div className="mobile-profile-hero mobile-v5-profile-hero"><button className="mobile-avatar mobile-avatar-button" onClick={() => document.getElementById("mobile-account-settings")?.scrollIntoView({ behavior: "smooth", block: "start" })} aria-label="打开资料设置">{profile.avatar_url ? <img src={resolveMediaUrl(profile.avatar_url, API_BASE)} alt="" /> : String(name).slice(0, 1).toUpperCase()}</button><div><h1>{name}</h1><p>{signature || "个性签名暂未提供"}</p></div></div>{notice && <div className="mobile-inline-notice" role="status">{notice}</div>}<section className="mobile-account-section" id="mobile-account-settings"><SectionTitle title="账号设置" /><div className="mobile-settings-list"><button onClick={() => avatarInput.current?.click()}>修改头像 <b>›</b></button><button onClick={() => setDialog("nickname")}>修改昵称 <b>›</b></button><button onClick={() => setDialog("password")}>修改密码 <b>›</b></button><button onClick={() => setDialog("email")}>绑定邮箱 <b>›</b></button></div></section><section className="mobile-learning-spaces"><SectionTitle title="学习空间" /><button className={`mobile-learning-space${mode === "course" ? " is-active" : ""}`} onClick={() => switchMode("course")}><span><strong>课程学习</strong><small>大学课程学习体系</small></span><b>›</b></button><button className={`mobile-learning-space${mode === "exam" ? " is-active" : ""}`} onClick={() => switchMode("exam")}><span><strong>11408考研中心</strong><small>真题、错题、计划、AI训练</small></span><b>›</b></button></section><section className="mobile-account-section"><SectionTitle title="服务" /><div className="mobile-settings-list"><button onClick={() => onNavigate("/m/profile/membership")}>会员中心 <b>›</b></button><button onClick={() => onNavigate("/m/profile/quota")}>额度使用 <b>›</b></button><button onClick={() => onNavigate("/m/profile/store")}>商城 <b>›</b></button></div></section><button className="mobile-logout-button" onClick={onLogout}>退出登录</button><MobileAccountDialog kind={dialog} user={user} profile={profile} onClose={() => setDialog("")} onUpdated={saveProfile} /></div>;
}
function MobileStore({ user }) { const state = useMobileRequest(async () => { const [membership, course, exam] = await Promise.all([jsonFetch(`/membership/summary?username=${encodeURIComponent(user.username)}`), jsonFetch("/membership/catalog?service_key=course_learning"), jsonFetch("/membership/catalog?service_key=exam_11408")]); return { membership, course, exam }; }, [user.username]); if (state.status !== "success") return <div className="mobile-page"><AsyncState state={state} empty={<EmptyState title="商城暂无可购买套餐" description="服务端没有返回可展示的套餐。" />} /></div>; const effectivePlan = state.data.membership?.effective_plan || state.data.membership; const groups = [["会员套餐", "当前会员权益", effectivePlan ? [effectivePlan] : []], ["课程权益", "课程学习", safeArray(state.data.course?.plans || state.data.course?.items || state.data.course)], ["11408套餐", "11408考研", safeArray(state.data.exam?.plans || state.data.exam?.items || state.data.exam)]]; const price = (plan) => { const cents = Number(plan?.price_cents); if (Number.isFinite(cents)) return cents === 0 ? "免费" : `¥${(cents / 100).toFixed(2)}`; return plan?.price ?? plan?.amount ?? "价格未提供"; }; return <div className="mobile-page mobile-store-page"><div className="mobile-page-heading"><div><h1>商城</h1><p>套餐与价格均由服务端会员目录提供。</p></div></div>{groups.map(([title, service, plans]) => <section className="mobile-store-group" key={title}><SectionTitle title={title} /><small className="mobile-data-note">{service}</small>{plans.length ? <div className="mobile-store-list">{plans.map((plan, index) => <article key={plan.id || plan.code || index} className="mobile-store-card"><strong>{displayText(plan, ["display_name", "plan_name", "name", "title", "plan", "current_plan"]) || "套餐名称缺失"}</strong><p>{displayText(plan, ["description", "summary"]) || "服务端未提供套餐说明。"}</p><b>{price(plan)}</b><button className="mobile-store-checkout" disabled title="当前移动端没有可复用的结算深链">结算入口暂未提供</button></article>)}</div> : <EmptyState compact title={`${title}暂无数据`} description="服务端没有返回可展示套餐。" />}</section>)}</div>; }
function MobileMembership({ user }) { const state = useMobileRequest(() => jsonFetch(`/membership/summary?username=${encodeURIComponent(user.username)}`), [user.username]); if (state.status !== "success") return <div className="mobile-page"><AsyncState state={state} empty={<EmptyState title="暂无会员数据" />} /></div>; const membership = state.data; const plan = membership?.effective_plan || membership; return <div className="mobile-page"><div className="mobile-page-heading"><div><span className="mobile-eyebrow">账号权益</span><h1>会员与权限</h1><p>当前账号的服务端会员状态。</p></div></div><section className="mobile-profile-card"><div><span>当前套餐</span><strong>{displayText(plan, ["display_name", "plan_name", "plan", "current_plan"]) || "套餐数据缺少名称"}</strong></div><div><span>会员状态</span><strong>{typeof membership.is_member === "boolean" ? (membership.is_member ? "生效中" : "免费") : "会员状态数据缺失"}</strong></div></section></div>; }
function MobileQuota({ user }) { const state = useMobileRequest(() => jsonFetch(`/me/quota?username=${encodeURIComponent(user.username)}`), [user.username]); if (state.status !== "success") return <div className="mobile-page"><AsyncState state={state} empty={<EmptyState title="暂无额度数据" />} /></div>; const quota = state.data; return <div className="mobile-page"><div className="mobile-page-heading"><div><span className="mobile-eyebrow">使用情况</span><h1>额度使用</h1><p>当前账号的服务端额度。</p></div></div><section className="mobile-profile-card"><div><span>剩余额度</span><strong>{quota.remaining ?? quota.remaining_quota ?? "额度数据缺失"}</strong></div><div><span>今日使用</span><strong>{quota.today_used ?? quota.used_today ?? "使用数据缺失"}</strong></div></section></div>; }

export default function MobileApp() {
  const [user, setUser] = useState(readStoredUser);
  const [authReady, setAuthReady] = useState(false);
  const [path, setPath] = useState(window.location.pathname + window.location.search);
  const [space, setSpace] = useState(readMobileSpace);
  const route = routeFromPath(path);
  useEffect(() => { let active = true; const stored = readStoredUser(); jsonFetch("/me", { method: "POST", body: JSON.stringify(stored?.username ? { username: stored.username } : {}) }).then((data) => { if (!active) return; if (data.user) { localStorage.setItem(USER_STORAGE_KEY, JSON.stringify(data.user)); setUser(data.user); } else { localStorage.removeItem(USER_STORAGE_KEY); setUser(null); } }).catch(() => { if (active) { localStorage.removeItem(USER_STORAGE_KEY); setUser(null); } }).finally(() => { if (active) setAuthReady(true); }); return () => { active = false; }; }, []);
  const navigate = useCallback((nextPath) => { window.history.pushState({}, "", nextPath); setPath(nextPath); if (!nextPath.startsWith("/m/ai/chat/")) window.scrollTo({ top: 0, behavior: "smooth" }); }, []);
  const updateUser = useCallback((nextUser) => { localStorage.setItem(USER_STORAGE_KEY, JSON.stringify(nextUser)); setUser(nextUser); }, []);
  useEffect(() => { const handlePath = () => setPath(window.location.pathname + window.location.search); const handleSpace = (event) => setSpace(event.detail === "exam" ? "exam" : readMobileSpace()); window.addEventListener("popstate", handlePath); window.addEventListener("mobile-space-change", handleSpace); return () => { window.removeEventListener("popstate", handlePath); window.removeEventListener("mobile-space-change", handleSpace); }; }, []);
  const logout = async () => { await fetch(`${API_BASE}/logout`, { method: "POST", credentials: "include" }).catch(() => {}); localStorage.removeItem(USER_STORAGE_KEY); setUser(null); navigate("/m"); };
  if (!authReady) return <main className="mobile-auth mobile-app"><LoadingState /></main>;
  if (!user) return <MobileAuth onAuthenticated={updateUser} />;
  let content = space === "exam" && route === "home" ? <MobileExam user={user} onNavigate={navigate} /> : <MobileHome user={user} onNavigate={navigate} />;
  if (route === "learn") content = <MobileLearning user={user} onNavigate={navigate} />;
  if (route === "knowledge") content = <MobileKnowledgeDetail user={user} onNavigate={navigate} />;
  if (route === "ai") content = <MobileAIHome user={user} onNavigate={navigate} />;
  if (route === "aichat") content = <MobileChat user={user} onNavigate={navigate} />;
  if (route === "practice") content = <MobilePractice user={user} onNavigate={navigate} />;
  if (route === "exam") content = <MobileExam user={user} onNavigate={navigate} />;
  if (route === "paperattempt") content = <MobilePastPaperAttempt user={user} onNavigate={navigate} />;
  if (route === "programming") content = <MobileProgramming user={user} onNavigate={navigate} />;
  if (route === "profile") content = <MobileProfile user={user} onLogout={logout} onNavigate={navigate} onUserUpdate={updateUser} />;
  if (route === "membership") content = <MobileMembership user={user} />;
  if (route === "quota") content = <MobileQuota user={user} />;
  if (route === "store") content = <MobileStore user={user} />;
  return <MobileLayout route={route} onNavigate={navigate} user={user} space={space}>{content}</MobileLayout>;
}
